#!/usr/bin/env bash
# IZI_FORMAT for a repository with more than one stack: picks the formatter
# by the edited file's directory and extension. Generated by /izi:kickoff;
# it's the project's script, edit it freely. Formatter failures are ignored.

set -uo pipefail
cd "$(dirname "$0")/.."
file="$1"
# Windows: Claude Code sends C:\... paths; Git Bash compares /c/... ones.
command -v cygpath >/dev/null 2>&1 && file="$(cygpath -u "$file")"

# One line per stack: directory|extensions|format command (gets the file, relative to the directory)
stacks=(
  "<directory>|<ext,ext>|<format command>"
)

for line in "${stacks[@]}"; do
  IFS='|' read -r dir exts cmd <<<"$line"
  rel="${file#"$PWD"/}"
  [[ "$rel" == "$dir"/* ]] || continue
  [[ ",$exts," == *",${rel##*.},"* ]] || continue
  (cd "$dir" && bash -c "$cmd \"\$1\"" _ "${rel#"$dir"/}") >/dev/null 2>&1
done
exit 0
